 {"slug": "ex05_pivot_unpivot", "problems": [
  {"title": "부서별 직무 인원 PIVOT", "cols": [("deptno","n"),("clerk","n"),("manager","n"),("salesman","n")],
   "rows": [(10,1,1,0),(20,2,1,0),(30,1,1,4)],
   "oracle": "SELECT deptno, NVL(c, 0), NVL(m, 0), NVL(s, 0) FROM (SELECT deptno, job FROM emp)\nPIVOT (COUNT(*) FOR job IN ('CLERK' AS c, 'MANAGER' AS m, 'SALESMAN' AS s))",
   "sqlserver": "SELECT deptno, [CLERK], [MANAGER], [SALESMAN] FROM (SELECT deptno, job, empno FROM emp) s\nPIVOT (COUNT(empno) FOR job IN ([CLERK], [MANAGER], [SALESMAN])) p",
   "note": "PIVOT 안의 COUNT 는 해당 칸에 행이 없으면 0 이다(Oracle COUNT(*) 도 0). NVL 은 안전장치.\nSQL Server PIVOT 은 COUNT(*) 를 받지 않아 COUNT(empno) 로 셌다."},
  {"title": "UNPIVOT 0 초과 칸", "cols": [("deptno","n"),("job","s"),("cnt","n")],
   "rows": [(10,"CLERK",1),(10,"MANAGER",1),(20,"CLERK",2),(20,"MANAGER",1),(30,"CLERK",1),(30,"MANAGER",1),(30,"SALESMAN",4)],
   "oracle": "SELECT deptno, job, cnt FROM (\n  SELECT * FROM (SELECT deptno, job FROM emp) PIVOT (COUNT(*) FOR job IN ('CLERK' AS clerk, 'MANAGER' AS manager, 'SALESMAN' AS salesman))\n) UNPIVOT (cnt FOR job IN (clerk AS 'CLERK', manager AS 'MANAGER', salesman AS 'SALESMAN')) WHERE cnt > 0",
   "sqlserver": "SELECT deptno, job, cnt FROM (\n  SELECT deptno, [CLERK], [MANAGER], [SALESMAN] FROM (SELECT deptno, job, empno FROM emp) s\n  PIVOT (COUNT(empno) FOR job IN ([CLERK], [MANAGER], [SALESMAN])) p\n) x UNPIVOT (cnt FOR job IN ([CLERK], [MANAGER], [SALESMAN])) u WHERE cnt > 0"}]},
